"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3925],{9205(e){e.exports=JSON.parse('{"title":"\uc54a\uc774 \uadf8\ub798\uc11c \uc778\uc99d \ud1a0\ud070\uc744 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud574\uc57c\ud558\ub294\uac70\uc8e0?","date":"2023-09-06","coverUrl":"/kudzu-based-bench/assets/notion/9fc7ff5cfb7d7e7d.png","html":"<h2 data-notion-block-id=\\"842c4496-9e4f-46fe-b24c-ea868549e437\\" id=\\"842c4496-9e4f-46fe-b24c-ea868549e437\\">\uc54a\uc774 \uadf8\ub798\uc11c \uc778\uc99d \ud1a0\ud070\uc744 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud574\uc57c\ud558\ub294\uac70\uc8e0?</h2><a href=\\"https://auth0.com/blog/secure-browser-storage-the-facts\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://auth0.com/blog/secure-browser-storage-the-facts</a><p data-notion-block-id=\\"b827c904-52ad-4f2e-8b50-e6c8d71354a3\\"><b>\uc2ec\uc724\uc12d</b>: \ud504\ub85c\uadf8\ub7a8\uc744 \uac1c\ubc1c\ud558\ub294 \uc774\uc0c1 \ubcf4\uc548\uc5d0 \uc2e0\uacbd\uc368\uc57c \ud569\ub2c8\ub2e4. \ub098\ub9cc\uc758 \uc791\uace0 \uc18c\uc911\ud55c \uc11c\ube44\uc2a4\uc758 \uc0ac\uc6a9\uc790\ub4e4\uc758 \uc815\ubcf4\ub97c \uc9c0\ucf1c\uc57c \ud558\ub2c8\uae4c\uc694. \uadf8\ub798\uc11c \uc11c\ube44\uc2a4\ub97c \ub9cc\ub4dc\ub294 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub294 \ud56d\uc0c1 \uc778\uc99d\uc774 \uc644\ub8cc\ub41c \ud1a0\ud070\uc744 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud560\uc9c0 \uac71\uc815\ud569\ub2c8\ub2e4. \uac16\uace0\uc628 \uae00\uc740 \ud1a0\ud070\uc758 \uc800\uc7a5 \ubc29\uc2dd\uc744 \uba85\ud655\ud558\uac8c \uc815\ud574\uc8fc\ub294 \uae00\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc624\ud788\ub824 \\"\ub108\uac00 \ubb58 \uc0dd\uac01\ud588\ub4e0 \uadf8 \ubc29\uc2dd\uc740 \uc704\ud5d8\ud560 \uc218 \uc788\uc5b4.\\"\ub97c \uc54c\ub824\uc8fc\ub294 \uae00\uc5d0 \uac00\uae5d\uc8e0(<code>Web Worker</code>\ub97c \uc0ac\uc6a9\ud55c \ubc29\uc2dd\uc744 \ubab0\ub790\ub2e4\uba74 \ub9d0\uc774\uc8e0!). \uae00\uc758 \ub9c8\ubb34\ub9ac\ub294 \\"<code>Web Worker</code>\ub97c \uc0ac\uc6a9\ud574\uc11c \uc0ac\uc6a9\uc790\uac00 \uc778\uba54\ubaa8\ub9ac \ubcc0\uc218\uc5d0 \uc811\uadfc\ud560 \uc218 \uc5c6\uac8c \ud558\uac70\ub098, \uc6b0\ub9ac \uc11c\ube44\uc2a4\ub97c \uc0ac\uc6a9\ud574!\\"\ub85c \ub05d\ub098\uc9c0\ub9cc \uc6b0\ub9ac\ub4e4\uc758 \ud074\ub77c\uc774\uc5b8\ud2b8\uc778 \uae30\ud68d\uc790\ub294 \ub9cc\ub9cc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \\"\ub85c\uadf8\uc778 \uc720\uc9c0 \uae30\ub2a5\\"\uc744 \uad6c\ud604\ud574\ub2ec\ub77c\uace0 \uc694\uccad\uc774 \ub4e4\uc5b4\uc654\ub2e4\uace0 \uac00\uc815\ud558\uc8e0. \uc774 \uae30\ub2a5\uc744 \uad6c\ud604\ud558\uae30 \uc704\ud574 <code>Web Storage</code> \uc911 \ud558\ub098\uc5d0 \uc800\uc7a5\ud574\uc57c \ud558\uace0, \uacb0\uad6d \uc704\ud5d8\uc5d0 \ub178\ucd9c\ub420 \uc218 \ubc16\uc5d0 \uc5c6\uc2b5\ub2c8\ub2e4. \\"\uadf8\ub7fc \uc5b4\ub5bb\uac8c \ud558\uc8e0?\\"\ub77c\uace0 \ubb3c\uc5b4\ubcf4\uba74 \\"\ub2e4 \uc704\ud5d8\ud558\ub2c8\uae4c \uc4f0\uc9c0 \ub9c8\ub77c\\"\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \uadf8\uac83\uc744 \uc804\ud574\uc8fc\ub824\uace0 \uae00\uc744 \uac00\uc838\uc628 \uac83\ub3c4 \uc544\ub2c8\uad6c\uc694. \uc81c\uac00 \uc0dd\uac01\ud558\ub294 \uacb0\ub860\uc740 \\"<b>\ubb34\uc5c7\uc744 \uc4f0\ub358\uac04 \uc704\ud5d8\uc5d0 \ub178\ucd9c\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \uc778\uc9c0\ud558\uace0, XSS\ub294 \ub9c9\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubcf4\ub294\uac8c \uc88b\ub2e4</b>\\"\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \ubb38\uc81c\uc5d0 \uc740\ud0c4\ud658\uc740 \uc5c6\uc73c\ub2c8\uae4c\uc694.</p><p data-notion-block-id=\\"1e39d40a-b6d6-46ab-9cba-1331406a8208\\"><b>\ucd5c\uc6d0\ube48</b>: \uacf5\uaca9 \ubc29\uc2dd\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc778\uc0c1\uae4a\uc740 \uae00\uc785\ub2c8\ub2e4. cookie \ubcf4\ub2e4\ub294 <code>localStoarge</code>\uac00 \uc548\uc815\uc801\uc774\uace0, \uadf8\ubcf4\ub2e4\ub294 <code>sessionStoarge</code>\uac00 \ub354 \uc548\uc815\uc801\uc774\uace0, \uadf8\ubcf4\ub2e4\ub294 <code>httpOnly</code> \ucfe0\ud0a4\uac00 \uc548\uc815\uc801\uc774\ub77c\ub294 \uac83\uc740 \uc0c1\uc2dd\uc774\uba70 \uc0ac\uc2e4\uc774\uc9c0\ub9cc, \uacb0\uad6d \uacf5\uaca9\uc744 \uc758\ub3c4\ud55c\ub2e4\uba74 \uc5b4\ub835\uc9c0 \uc54a\uac8c \ub2e8\uc21c\ud55c \uacf5\uaca9(XSS)\uc73c\ub85c \uc811\uadfc\uc774 \uac00\ub2a5\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ucda9\ubd84\ud788 \uc778\uc9c0\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\uc694. \uc774\ub7f0 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uc788\ub2e4\uba74, \ud3fc \uad00\ub828 \uae30\ub2a5\uc744 \uac1c\ubc1c\ud560 \ub54c \uc774\ub97c \ubc29\uc9c0\ud574\uc57c \ud55c\ub2e4\ub294\uac78 \uc78a\uc9c0 \uc54a\uc744 \uc218 \uc788\uc744 \uac83 \uac19\ub124\uc694. \ucd5c\uc120\uc758 \ubc29\uc5b4\ub294 \uacf5\uaca9\uc774\ub77c\ub294 \uc810\uc744 \ub2e4\uc2dc \ud55c\ubc88 \uae68\uc6b0\uce58\uace0 \uac11\ub2c8\ub2e4. \ud83d\ude32</p><h2 data-notion-block-id=\\"9e5bb35f-15dd-4263-a1f5-252937acdbc6\\" id=\\"9e5bb35f-15dd-4263-a1f5-252937acdbc6\\">React\uc5d0\uc11c polymorpic component \ub9cc\ub4e4\uae30(w. asChild)</h2><a href=\\"https://www.jacobparis.com/content/react-as-child\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jacobparis.com/content/react-as-child</a><p data-notion-block-id=\\"3fc18037-f831-4bfb-a36a-eba4d84856eb\\"><b>\uc2ec\uc724\uc12d</b>: \xa0\ubcf4\ud1b5 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub9c8\ub828\ud560 \ub54c\uc5d0 \ub9ce\uc740 \uac83\uc744 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8 \uc911\uc5d0\uc11c\ub294 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ucee4\uc2a4\ud140\ud558\uae30 \uc27d\uac8c \ud558\ub294 \uac83\ub3c4 \uadf8 \uc911 \ud558\ub098\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. Button \uc2a4\ud0c0\uc77c\uc774 <code>&#x3C;button></code>\ud0dc\uadf8\uc5d0\ub9cc \uc4f0\uc774\uc9c0\ub9cc \uc54a\uace0 <code>&#x3C;a></code>\ud0dc\uadf8\ub098 \ub2e4\ub978 \ucee4\uc2a4\ud140 \ucef4\ud3ec\ub10c\ud2b8\uc5d0\ub3c4 \uc0ac\uc6a9\ub418\ub2c8\uae4c\uc694. \uc774 \ub54c \ub9ce\uc774 \uc0ac\uc6a9\ub418\ub294 \ubc29\ubc95\uc774 Chakra UI\uc758 <code>as</code> props, MUI\uc758 <code>component</code> props \uac19\uc774 element \uc774\ub984\uc774\ub098 \ucef4\ud3ec\ub10c\ud2b8 \uc790\uccb4\ub97c \ub118\uae30\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4. \uc774\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc740 <a href=\\"https://blog.logrocket.com/build-strongly-typed-polymorphic-components-react-typescript\\">\uc790\uc138\ud558\uac8c TypeScript \uad6c\ud604\ud558\ub294 \uae00</a> (<a href=\\"https://kciter.so/posts/polymorphic-react-component\\">\ud55c\uad6d\uc5b4\ub85c \uc4f0\uc5ec\uc9c4 \uae00(\ubc88\uc5ed \uc544\ub2d8)</a>\ub3c4 \uc788\ub124\uc694!)\ub97c \ucc38\uace0\ud558\uc138\uc694. \ud558\uc9c0\ub9cc \uc774 \uae30\uc0ac\ub294 Radix\uc758 `asChild`(next/link\uc758 <code>passHref</code>\uc640 \ube44\uc2b7\ud560\uc9c0\ub3c4\uc694)\uc5d0 \uc8fc\ubaa9\ud558\uace0 \uc774\ub97c \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc774\ub77c\uba74 \uaf2d \ubcf4\uc168\uc73c\uba74 \ud569\ub2c8\ub2e4!</p><p data-notion-block-id=\\"e49124ea-b045-46b8-9000-51e047e0576d\\"><b>\ucd5c\uc6d0\ube48</b>: <a href=\\"https://www.radix-ui.com/\\">Radix UI</a>\ub294 \uc790\uc720\ub3c4 \ub192\uc740 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \uad6c\ud604\ud558\uae30 \uc704\ud574 <code>asChild</code> \ud328\ud134, <code>Compound</code> \ud328\ud134 \ub4f1\uc744 \uc801\uc808\ud788 \uc0ac\uc6a9\ud574 Headless\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \uc6b0\uc218 \uc0ac\ub840\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc811\uadfc\uc131\ub3c4 \ucda9\ubd84\ud788 \uace0\ub824\ud574 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83 \ub9cc\uc73c\ub85c\ub3c4 \ubc30\uc6b8 \uc810\uc774 \ub9ce\uc740\ub370, <code>asChild</code>\ud328\ud134\uc744 \uad6c\ud604\ud558\uba70 \uc8fc\ub41c \ud658\uacbd\uc778 TypeScript + React \uc5d0\uc11c React Element\uc640 HTML Element \uc0ac\uc774\uc758 \uac2d\uc744 \uba54\uafd4\ub098\uac00\ub294 \uacfc\uc815\uc774 \ud765\ubbf8\ub86d\ub124\uc694. \ucef4\ud3ec\ub10c\ud2b8\uc758 \ucd94\uc0c1\ud654\uac00 \uc911\uc694\uc2dc\ub418\ub294 \uac00\uc6b4\ub370, leaf \ub178\ub4dc\uc5d0 \uac00\uae4c\uc6b4 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ucd94\uc0c1\ud654\ud558\ub824\uba74 \ubd84\uba85\ud788 \uc54c\uc544\uc57c \ud560 \uc810\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30\uc5d0 \ucd94\ucc9c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"3107fecb-1574-47c1-94f0-f1a53442a6a4\\" id=\\"3107fecb-1574-47c1-94f0-f1a53442a6a4\\">React\uc758 \ub3d9\uc2dc\ubaa8\ub4dc \uc791\ub3d9 \uc6d0\ub9ac</h2><a href=\\"https://andreigatej.dev/blog/the-underlying-mechanisms-of-reacts-concurrent-mode/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://andreigatej.dev/blog/the-underlying-mechanisms-of-reacts-concurrent-mode/</a><p data-notion-block-id=\\"1328b336-aed7-4221-ad5b-c2b90188fc1d\\"><b>\uc2ec\uc724\uc12d</b>: React\uc758 \ub3d9\uc2dc\ubaa8\ub4dc\uc758 <code>startTransition</code>\uc774 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uac00\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4(\uc5b4\ub835\uc2b5\ub2c8\ub2e4). \ub9ac\uc561\ud2b8 \ub0b4\ubd80\uc758 \ub3d9\uc791\uc6d0\ub9ac\ub97c \uc124\uba85\ud558\uace0 \uc788\uae30\uc5d0 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub9ac\uc561\ud2b8\uc758 \uc804\ubc18\uc801\uc778 \ub3d9\uc791 \uc6d0\ub9ac\ub97c \ubaa8\ub974\uc2dc\ub294 \ubd84\uc740 <a href=\\"https://blog.isquaredsoftware.com/2020/05/blogged-answers-a-mostly-complete-guide-to-react-rendering-behavior/\\">React \ub80c\ub354\ub9c1 \ub3d9\uc791\uc5d0 \ub300\ud55c (\uac70\uc758) \uc644\ubcbd\ud55c \uac00\uc774\ub4dc</a> (<a href=\\"https://velog.io/@superlipbalm/blogged-answers-a-mostly-complete-guide-to-react-rendering-behavior\\">\ud55c\uad6d\uc5b4 \ubc88\uc5ed</a>)\uc744 \ubcf4\uc2dc\uace0, \ub354 \uc790\uc138\ud55c \ub3d9\uc791\uc6d0\ub9ac\ub97c \uc6d0\ud558\uc2dc\ub294 \ubd84\uc740 <a href=\\"https://goidle.github.io/react/in-depth-react18-intro/\\">React 18 \ud1ba\uc544\ubcf4\uae30</a>(\ucf54\ub4dc \uae30\ubc18\uc73c\ub85c \ud558\uae30 \ub54c\ubb38\uc5d0 \ud604\uc7ac \uc0ac\uc6a9\ub418\uc9c0 \uc54a\ub294 \uac1c\ub150\uc774 \uc788\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.)\uc744 \ubcf4\uc138\uc694. \uac1c\ub150\ub9cc \ubcf4\uc2dc\uae38 \uc6d0\ud55c\ub2e4\uba74 <a href=\\"https://github.com/reactjs/rfcs/blob/main/text/0212-react-18.md\\">React 18 RFC</a>\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"61f142ad-0ecd-4ac4-8397-2bf0de9f948d\\"><b>\ucd5c\uc6d0\ube48</b>: \uacf5\uc2dd \ubb38\uc11c\uc758 <a href=\\"https://ko.react.dev/blog/2022/03/29/react-v18#what-is-concurrent-react\\">Concurrent Mode\uc5d0 \ub300\ud55c \uc18c\uac1c\uae00</a>\uc5d0\uc11c\ub294 \uc774\ub7ec\ud55c \ub0b4\uc6a9\uc744 \ucc3e\uc544\ubcf4\uae30 \ud798\ub4e0\ub370, \ud575\uc2ec \ub3d9\uc791 \uc6d0\ub9ac\uc778 \\"\ub80c\ub354\ub9c1\uc744 \uc911\uc9c0\ud558\uace0 \ube0c\ub77c\uc6b0\uc800\uc758 \uba54\uc778 \uc2a4\ub808\ub4dc\uc5d0 \ub118\uae30\ub294 \uacfc\uc815\\"\uc5d0 \ub300\ud574 \ubcf5\uc7a1\ud55c \ucd94\uac00 \uc0c1\ud669 \uc5c6\uc774 \uc774\ud574\ud558\uae30 \uc27d\uac8c \uc608\uc2dc\ub97c \ub4e4\uc5b4 \uc124\uba85\ud569\ub2c8\ub2e4. <code>useTransition</code>\ud6c5\uc744 <b>\uc815\ud655\ud788</b> \uc0ac\uc6a9\ud558\ub824\uba74 \ubc18\ub4dc\uc2dc \uc774\ud574\ud574\uc57c \ud558\ub294 \ub0b4\uc6a9\uc774\ub77c\uace0 \uc0dd\uac01\uc774 \ub4dc\ub124\uc694.</p>"}')}}]);